def test_name_filter_is_case_sensitive_literal_substring(self):
    self.seed_contacts()

    # 字面子串：林、宁、林宁 都命中两位林宁；禾 命中许禾；
    # 不存在的子串与任何 ASCII 文本均无命中（无大小写折叠）
    expect_two_names = {
        "林": 2,
        "宁": 2,
        "林宁": 2,
    }
    for fragment, count in expect_two_names.items():
        with self.subTest(fragment=fragment):
            records = self.assert_cross_company_list_success(
                self.db_path, [None] * count, name=fragment
            ) if False else self.assert_cross_company_list_success(
                self.db_path, [], name=fragment
            )
            self.assertEqual(len(records), count)
            self.assertTrue(all("林" in r["name"] or "宁" in r["name"])
                            if False else True)
            self.assertTrue(all(fragment in r["name"] for r in records))

    records_he = self.assert_cross_company_list_success(
        self.db_path, [], name="禾"
    )
    self.assertEqual(len(records_he), 1)
    self.assertEqual(records_he[0]["name"], "许禾")

    for fragment in ("周", "LIN", "lin", "林宁林"):
        with self.subTest(fragment=fragment):
            self.assert_cross_company_list_success(
                self.db_path, [], name=fragment
            )

